/**
 * Typed access to the paper's compact benchmark comparison table (Table 1).
 * The JSON is generated by scripts/export_paper.py from the paper source;
 * exact counts come from the full comparison table in the appendix and are
 * checked against the low / mid / high buckets.
 */
import data from '../data/paper/comparison.json';

export type Mark = 'yes' | 'partial' | 'no' | 'na';
export type Bucket = 'low' | 'mid' | 'high' | 'na';
export type CellValue = Mark | Bucket;
export type ColumnGroup = 'realism' | 'trustworthy';

export interface ComparisonColumn {
  id: string;
  label: string;
  /** Design principle number (1 to 11) this column marks. */
  principle: number;
  group: ColumnGroup;
  kind: 'mark' | 'bucket';
}
export interface ComparisonRow {
  name: string;
  ours: boolean;
  values: Record<string, CellValue>;
  /** Exact counts for bucket columns, as printed in the paper's full table (for example "69.9" or "~500"). */
  counts: Record<string, string>;
}
export interface ComparisonGroup {
  id: 'widely-used' | 'closest' | 'ours';
  title: string;
  rows: ComparisonRow[];
}

export const COMPARISON_COLUMNS = data.columns as ComparisonColumn[];
export const COMPARISON_GROUPS = data.groups as ComparisonGroup[];
/** Thresholds of the low / mid / high buckets, per bucket column id. */
export const BUCKET_RULES = data.bucketRules as Record<string, Record<'low' | 'mid' | 'high', string>>;
export const OTHER_BENCHMARKS_REVIEWED = data.otherBenchmarksReviewed;

/** Columns that mark a given design principle (P2 and P10 have more than one). */
export const columnsForPrinciple = (principle: number) => COMPARISON_COLUMNS.filter(column => column.principle === principle);
